export function classifyStructure(path){const n=path.toLowerCase();
if(/headlight|tail light|signal|led|instruments|ecu|harness|rectifier|regulator/.test(n))return 'lights';
if(/front.*(tire|rim|rotor|caliper|brake|axle|spacer|abs)|fromt rotor/.test(n))return 'xyDrive';
if(/rear.*(tire|wheel|rotor|caliper|brake|axle|abs|fluid)/.test(n))return 'xyGuide';
if(/chain|sprocket|countershaft/.test(n))return 'hotend';
if(/fork|shock|swing|linkage|piston chrome/.test(n))return 'zGuide';
if(/handlebar|grips|bar |bar end|controls|lever|clamp|head bearing|head stem|switch|button|reach adjuster/.test(n))return 'zDrive';
if(/tank|fuel cap|seat|fender|plastics|scoop|hugger/.test(n))return 'panels';
if(/airbox|throttle|fuel rail|exhaust|header|radiator|raditator|coolant|thermostat|water pump|o2 sensor|oil cooler|coupl/.test(n))return 'cooling';
if(/frame|rearset|pegs|kickstand|engine mount/.test(n))return 'bed';
if(/crank|cylinder|clutch|stator|valve cover|timing|oil |cct|cam chain|coilpack|starter motor|jacket|breather/.test(n))return 'extruder';
return 'aux';}